struct V { int value; };
struct B : virtual V {};
struct C : virtual V { int guard; };
struct D : B, C {};
int read(B& b) { return b.value; }
int main() {
  D d;
  d.guard = 13;
  d.value = 7;
  return read(d) == 7 ? 0 : 1;
}

namespace std { class type_info { public: bool operator==(const type_info&) const; }; }
int bad;
struct V { virtual void f() {} };
struct A : virtual V { A(); };
A::A() {
  V& v = *this;
  if (!(typeid(v) == typeid(A))) ++bad;
  if (dynamic_cast<void*>(&v) != static_cast<void*>(this)) ++bad;
}
struct P { virtual void p() {} };
struct D : P, A {};
int main() { D d; return bad; }

struct V { int value; V(int v = 3) : value(v) {} };
struct A : virtual V {};
struct D : A { D(const A& a) : V(9), A(a) {} };
int main() { A a; a.value = 7; D d(a); return d.value != 9; }

int calls;
struct V {};
struct B : virtual V {
  B() {}
  B(B&) { ++calls; }
  static void* operator new(unsigned long, void*, int) noexcept { return 0; }
};
int main() { B b; B* p = new ((void*)0, 0) B(b); return p != 0 || calls != 0; }

typedef decltype(sizeof(0)) size_type;
void* operator new(size_type, void*) noexcept;
int calls;
struct A {};
struct B : virtual A { B() {} B(B&) { ++calls; } };
int main() { B b; B* p = new ((void*)0) B(b); return p != 0 || calls != 0; }
